def nombre_de_tournees(commandes):
    """Renvoie le nombre de tournées du chariot de 6 casiers pour sortir toute la file, une commande ne se coupe pas."""
    tournees = 0
    place = 0
    for casiers in commandes:
        if casiers > place:
            tournees += 1
            place = 6
        place -= casiers
    return tournees
